def wk2m(wk):
    m={1:"Jan26",2:"Jan26",3:"Jan26",4:"Jan26",5:"Feb26",6:"Feb26",7:"Feb26",8:"Feb26",
       9:"Mar26",10:"Mar26",11:"Apr26",12:"Apr26",13:"May26",16:"May26",
       17:"Jun26",18:"Jun26",19:"Jun26",20:"Jun26",21:"Jun26",22:"Jun26",23:"Jun26"}
    return m.get(wk,"Unknown")

# ── DRIVE ──────────────────────────────────────────────────────────────────────
def get_drive_service():
    creds = Credentials(token=None,refresh_token=st.secrets["GOOGLE_REFRESH_TOKEN"],
        token_uri="https://oauth2.googleapis.com/token",
        client_id=st.secrets["GOOGLE_CLIENT_ID"],client_secret=st.secrets["GOOGLE_CLIENT_SECRET"],
        scopes=["https://www.googleapis.com/auth/drive.readonly"])
    return build("drive","v3",credentials=creds,cache_discovery=False)

@st.cache_data(ttl=300, show_spinner=False)
def load_all_data():
    try: svc = get_drive_service()
    except Exception as e: st.error(f"Auth error: {e}"); return None
    dfs=[]
    for fid in FILE_IDS:
        try:
            buf=io.BytesIO(); dl=MediaIoBaseDownload(buf,svc.files().get_media(fileId=fid))
            done=False
            while not done: _,done=dl.next_chunk()
            buf.seek(0); dfs.append(pd.read_csv(buf,low_memory=False,on_bad_lines="skip"))
        except: pass
    return pd.concat(dfs,ignore_index=True) if dfs else None

# ── PROCESS ────────────────────────────────────────────────────────────────────
def safe_col(df, names):
    for n in names:
        if n in df.columns:
            c = df[n]
            if isinstance(c, pd.DataFrame): c = c.iloc[:,0]
            c = c.squeeze()
            return pd.Series(c.values, name=n)
    return pd.Series([""]*len(df))

def process_data(df):
    out = pd.DataFrame()
    out["rc"]     = safe_col(df,["RC Name"])
    out["zone"]   = safe_col(df,["Zone"])
    out["week"]   = safe_col(df,["Week"])
    out["result"] = safe_col(df,["Result"])
    out["type"]   = safe_col(df,["RTO / RVP","RTO / RVP Status"])
    out["reason"] = safe_col(df,["QA remark"])
    out["vert"]   = safe_col(df,["Vertical 1"])
    out["result"] = out["result"].fillna("").astype(str).str.strip().str.lower()
    out = out[out["result"].isin(["pass","fail"])].copy()
    if len(out)==0: return None
    out["type"]   = out["type"].fillna("RTO").astype(str).str.strip().str.upper().str[:3]
    out["type"]   = out["type"].where(out["type"].isin(["RTO","RVP"]),"RTO")
    out["week"]   = pd.to_numeric(out["week"], errors="coerce").fillna(0).astype(int)
    out = out[out["week"]>0]
    out["rc"]     = out["rc"].fillna("").astype(str).str.strip().map(lambda x:REV.get(x,x))
    out["zone"]   = out["zone"].fillna("").astype(str).str.strip()
    out = out[(out["rc"]!="") & (out["zone"]!="")]
    out["vert"]   = out["vert"].fillna("Electronics").astype(str).str.strip()
    out["vert"]   = out["vert"].str.replace(r"^RTO[_ ]+","",regex=True).str.replace(r"^RVP[_ ]+","",regex=True).str.strip()
    out.loc[out["vert"]=="","vert"] = "Electronics"
    out["reason"] = out["reason"].fillna("").astype(str).str.strip()
    out.loc[out["reason"].str.lower().isin(["no issue","no issue.",""]), "reason"] = ""
    out["month"]  = out["week"].map(wk2m)
    return out.reset_index(drop=True)

# ── BUILD JS ───────────────────────────────────────────────────────────────────
def build_js_data(df):
    rc_zones = dict(df.groupby("rc")["zone"].first())
    stats    = defaultdict(lambda: defaultdict(lambda: defaultdict(lambda:[0,0])))
    rd_agg   = defaultdict(lambda: defaultdict(lambda: defaultdict(lambda: defaultdict(lambda: defaultdict(lambda:0)))))
    reasons_overall=Counter(); reasons_rto=Counter(); reasons_rvp=Counter()
    reasons_by_zone={"overall":defaultdict(Counter),"rto":defaultdict(Counter),"rvp":defaultdict(Counter)}
    reasons_by_rc  ={"overall":defaultdict(Counter),"rto":defaultdict(Counter),"rvp":defaultdict(Counter)}

    for _,row in df.iterrows():
        rc,zone,wk,typ,res,vert,reason,month = row["rc"],row["zone"],int(row["week"]),row["type"],row["result"],row["vert"],row["reason"],row["month"]
        p=1 if res=="pass" else 0
        for key in [wk,month]:
            stats[rc][key][typ][0]+=1; stats[rc][key]["overall"][0]+=1
            stats[rc][key][typ][1]+=p; stats[rc][key]["overall"][1]+=p
        if res=="fail" and reason:
            reasons_overall[reason]+=1
            rk="rto" if typ=="RTO" else "rvp"
            (reasons_rto if typ=="RTO" else reasons_rvp)[reason]+=1
            reasons_by_zone["overall"][zone][reason]+=1; reasons_by_zone[rk][zone][reason]+=1
            reasons_by_rc["overall"][rc][reason]+=1;    reasons_by_rc[rk][rc][reason]+=1
            rd_agg[rc][month][wk][typ][vert+"\x00"+reason]+=1

    def gs(rc,k,t): return stats.get(rc,{}).get(k,{}).get(t,[0,0])
    def gbl(k,t):
        tt,pp=0,0
        for rc in stats: v=stats[rc].get(k,{}).get(t,[0,0]); tt+=v[0]; pp+=v[1]
        return [tt,pp]
    def mf(d): return ",".join(k+":"+json.dumps(v) for k,v in d.items() if v[0]>0)
    def wf(d): return ",".join(str(k)+":"+json.dumps(v) for k,v in d.items() if v[0]>0)

    rc_objs=[]
    for rc,zone in sorted(rc_zones.items(),key=lambda x:(x[1],x[0])):
        wo={w:gs(rc,w,"overall") for w in LAST7WKS}
        if sum(v[0] for v in wo.values())==0: continue
        mo={m:gs(rc,m,"overall") for m in MONTHS}; mr={m:gs(rc,m,"RTO") for m in MONTHS}; mv={m:gs(rc,m,"RVP") for m in MONTHS}
        wr={w:gs(rc,w,"RTO") for w in LAST7WKS};   wv={w:gs(rc,w,"RVP") for w in LAST7WKS}
        rr=dict(reasons_by_rc["overall"].get(rc,Counter()).most_common(8))
        rc_objs.append("{rc:"+json.dumps(rc)+",zone:"+json.dumps(zone)+
            ",mth:{overall:{"+mf(mo)+"},rto:{"+mf(mr)+"},rvp:{"+mf(mv)+"}}"+
            ",wk:{overall:{"+wf(wo)+"},rto:{"+wf(wr)+"},rvp:{"+wf(wv)+"}}"+
            ",reasons:"+json.dumps(rr)+"}") 

    rd_objs=[]
    for rc in rd_agg:
        flat=[]
        for m,wkd in rd_agg[rc].items():
            for wk,typs in wkd.items():
                for typ,vrd in typs.items():
                    for vr_key,cnt in vrd.items():
                        v,r=vr_key.split("\x00",1)
                        flat.append({"m":m,"w":wk,"t":typ,"v":v,"r":r,"c":cnt})
        rd_objs.append("{rc:"+json.dumps(rc)+",d:"+json.dumps(flat)+"}")

    wko={w:gbl(w,"overall") for w in ALL_WKS}; wkr={w:gbl(w,"RTO") for w in ALL_WKS}; wkv={w:gbl(w,"RVP") for w in ALL_WKS}
    mto={m:gbl(m,"overall") for m in MONTHS};  mtr={m:gbl(m,"RTO") for m in MONTHS};  mtv={m:gbl(m,"RVP") for m in MONTHS}
    top6=[r for r,_ in reasons_overall.most_common(6)]
    chart_data={r:[0]*len(LAST7WKS) for r in top6}
    for rc in rd_agg:
        for m,wkd in rd_agg[rc].items():
            for wk,typs in wkd.items():
                if wk in LAST7WKS:
                    for typ,vrd in typs.items():
                        for vr_key,cnt in vrd.items():
                            r=vr_key.split("\x00",1)[1]
                            if r in chart_data: chart_data[r][LAST7WKS.index(wk)]+=cnt
    all_verts=sorted(set(df["vert"].dropna().unique())-{""})

    def dec():
        out=[]; seen=set()
        for rc,zone in rc_zones.items():
            for typ in ["overall","RTO","RVP"]:
                wv2={}
                for w in LAST7WKS:
                    v=stats[rc].get(w,{}).get(typ,[0,0])
                    if v[0]>0: wv2[w]=round(v[1]/v[0]*100,1)
                if len(wv2)<3: continue
                e=[wv2[w] for w in LAST7WKS[:3] if w in wv2]
                l=[wv2[w] for w in LAST7WKS[4:] if w in wv2]
                if not e or not l: continue
                ae,al=sum(e)/len(e),sum(l)/len(l); drop=round(ae-al,1)
                if drop<=1.5 or (rc,typ) in seen: continue
                seen.add((rc,typ))
                tr=list(reasons_by_rc["overall"].get(rc,Counter()).keys())
                obs=("🔴 Critical." if drop>15 else "🟠 Significant." if drop>7 else "🟡 Moderate.")+f" {typ} down {drop}%."
                out.append({"rc":rc,"zone":zone,"type":typ,"avg_early":round(ae,1),"avg_late":round(al,1),"drop":drop,"wk_vals":{str(w):v for w,v in wv2.items()},"top_reason":(tr[0][:60] if tr else ""),"obs":obs})
        return sorted(out,key=lambda x:-x["drop"])[:25]

    lines=[
        "const MONTHS="+json.dumps(MONTHS)+";",
        "const MLABELS="+json.dumps(MLABELS)+";",
        "const LAST7WKS="+json.dumps(LAST7WKS)+";",
        "const ALL_WKS="+json.dumps(ALL_WKS)+";",
        "const ALL_VERTS="+json.dumps(all_verts)+";",
        "const REASONS_OVERALL="+json.dumps(dict(reasons_overall.most_common(12)))+";",
        "const REASONS_RTO="+json.dumps(dict(reasons_rto.most_common(12)))+";",
        "const REASONS_RVP="+json.dumps(dict(reasons_rvp.most_common(12)))+";",
        "const REASONS_BY_ZONE="+json.dumps({"overall":{z:dict(c.most_common(8)) for z,c in reasons_by_zone["overall"].items()},"rto":{z:dict(c.most_common(8)) for z,c in reasons_by_zone["rto"].items()},"rvp":{z:dict(c.most_common(8)) for z,c in reasons_by_zone["rvp"].items()}})+";",
        "const REASONS_BY_RC="+json.dumps({"overall":{rc:dict(c.most_common(8)) for rc,c in reasons_by_rc["overall"].items()},"rto":{rc:dict(c.most_common(8)) for rc,c in reasons_by_rc["rto"].items()},"rvp":{rc:dict(c.most_common(8)) for rc,c in reasons_by_rc["rvp"].items()}})+";",
        "const WK_OV={"+",".join(str(k)+":"+json.dumps(v) for k,v in wko.items() if v[0]>0)+"}",
        "const WK_RTO={"+",".join(str(k)+":"+json.dumps(v) for k,v in wkr.items() if v[0]>0)+"}",
        "const WK_RVP={"+",".join(str(k)+":"+json.dumps(v) for k,v in wkv.items() if v[0]>0)+"}",
        "const MTH_OV={"+",".join('"'+k+'"'+":"+json.dumps(v) for k,v in mto.items() if v[0]>0)+"}",
        "const MTH_RTO={"+",".join('"'+k+'"'+":"+json.dumps(v) for k,v in mtr.items() if v[0]>0)+"}",
        "const MTH_RVP={"+",".join('"'+k+'"'+":"+json.dumps(v) for k,v in mtv.items() if v[0]>0)+"}",
        "const DECLINING="+json.dumps(dec())+";",
        "const TOP6_REASONS="+json.dumps(top6)+";",
        "const CHART_DATA="+json.dumps(chart_data)+";",
        "const TREND_WKS="+json.dumps(LAST7WKS)+";",
        "const RC_DATA=[\n"+",\n".join(rc_objs)+"\n];",
        "const REASON_DATA=[\n"+",\n".join(rd_objs)+"\n];",
    ]
    return "\n".join(lines), len(df)

# ── MAIN ───────────────────────────────────────────────────────────────────────
def main():
    with st.spinner("🔄 Loading data from Google Drive..."):
        raw_df = load_all_data()
    if raw_df is None:
        st.error("❌ Could not load data. Check Drive connection."); return
    with st.spinner("⚙️ Processing..."):
        df = process_data(raw_df)
    if df is None or len(df)==0:
        st.error("❌ No valid data found."); return
    with st.spinner("📊 Building dashboard..."):
        js_data, total = build_js_data(df)

    # Get template and inject data
    template = base64.b64decode(TEMPLATE_B64).decode("utf-8")
    html = template.replace("DATABLOCK", js_data)
    html = html.replace(">1,27,871<", f">{total:,}<")

    # Render via components.html - the ONLY reliable way in Streamlit
    # Encode to handle unicode/emoji characters
    html_clean = html.encode("utf-8","replace").decode("utf-8")
    components.html(html_clean, height=7000, scrolling=False)

if __name__ == "__main__":
    main()
